head.script:
scwin.getToday = function() {
    var date = new Date();
    var dd = date.getDate() > 9 ? date.getDate() : '0' + date.getDate();
    var mm = date.getMonth() > 8 ? date.getMonth() + 1 : '0' + (date.getMonth() + 1);
    var yy = date.getFullYear();
    var today = yy + '-' + mm + '-' + dd;
    return today;
}
scwin.checkVal = function() {
    return scwin.getToday() === WebSquare.wUnit.getObjById('wq_uuid_4_input').value;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. inputCalendar_WPF-988_(WSQ-2237).xml 실행한다.
    //1. Run inputCalendar_WPF-988_ (WSQ-2237) .xml.
    //Test step 2. setCurrentDate = true로 설정하고 실행한다.
    //2. Set and run setCurrentDate = true.
    //Verify 2. 현재날짜가 Default로 보여진다.(이전에는 속성값이 비활성화되어 스튜디오의 속성에서 보이지않음)
    //2. The current date is shown as Default (previously the attribute value is disabled and not visible in the studio"s properties)
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_4_input').value == scwin.getToday()","true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 07-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
